import {people,relationships} from './data.js';
import {requireAI} from './chat.js';
import {requestJSON} from './openrouter.js';
import {VOICE_PROMPT,validateVoiceDraft,validGraph} from './voice-core.js';
import {FamilyCharts} from './charts.js';
const $=id=>document.getElementById(id),storageKey='family-history-reviewed-voice-v1';
let recording=false,recognition=null,recorder=null,stream=null,timer=null,queue=[],processing=false,controller=null,pending='',story='',audioParts=[],draftPeople=[],draftLinks=[],segments=[],settings=null,draw=null,refresh=()=>{};
const clean=s=>s.normalize('NFKC').toLocaleLowerCase().trim();
let saved={people:[],links:[],stories:[]};
export function restoreVoice(){try{const value=JSON.parse(localStorage.getItem(storageKey)||'null');if(value&&Array.isArray(value.people)&&Array.isArray(value.links)&&Array.isArray(value.stories)&&value.people.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.events)&&typeof p.bio==='string'&&Number.isFinite(p.row)&&Number.isFinite(p.col))&&validGraph([...people,...value.people],[...relationships,...value.links])){saved=value;people.push(...value.people);relationships.push(...value.links);}}catch{/* Invalid or inaccessible browser storage does not modify the tree. */}}
function status(text){$('voice-status').textContent=text;}
function renderDraft(){draw.render(draftPeople.map((p,i)=>({id:p.id,name:p.name,branch:'Draft',row:0,col:i})),draftLinks.map(l=>[l.from,l.to,l.type]),'network',draftPeople[0]?.id,[]);$('voice-count').textContent=`${draftPeople.length} proposed people · ${draftLinks.length} proposed links · ${segments.filter(s=>s.status==='pending'||s.status==='running').length} segments waiting · ${segments.filter(s=>s.status==='failed').length} need retry`;$('voice-review').disabled=recording||processing||queue.length>0||!draftPeople.length;$('voice-retry').hidden=!segments.some(s=>s.status==='failed');}
async function pump(){if(processing)return;processing=true;
 while(queue.length){const item=queue.shift();item.status='running';renderDraft();status(recording?'Listening · processing completed speech…':'Processing transcript…');controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);
 try{const r=await requestJSON({...requireAI(),prompt:VOICE_PROMPT,input:{segment:item.text,earlierNames:draftPeople.map(p=>p.name)},signal:controller.signal});const d=validateVoiceDraft(r.raw,item.text);if(!d)throw Error('Unsupported or ungrounded extraction. Segment retained for retry.');
 for(const p of d.people){let node=draftPeople.find(n=>clean(n.name)===clean(p.name));if(!node){node={id:'voice-'+crypto.randomUUID(),name:p.name,quotes:[]};draftPeople.push(node);}if(!node.quotes.includes(p.quote))node.quotes.push(p.quote);}
 for(const l of d.links){const from=draftPeople.find(n=>clean(n.name)===clean(l.from)).id,to=draftPeople.find(n=>clean(n.name)===clean(l.to)).id;if(!draftLinks.some(x=>x.from===from&&x.to===to&&x.type===l.type))draftLinks.push({from,to,type:l.type,quote:l.quote});}
 item.status='done';item.meta=r.meta;
 }catch(e){item.status='failed';item.error=e.name==='AbortError'?'Request cancelled or timed out.':e.message;status(item.error);}finally{clearTimeout(timeout);controller=null;renderDraft();}}
 processing=false;renderDraft();status(recording?'Listening · tree proposals update as speech is processed.':segments.some(s=>s.status==='failed')?'Some transcript segments need retry. Review stays available; failed segments have not been incorporated.':'Ready to review. Nothing has changed in the approved tree.');}
function flush(){const text=pending.trim();if(!text)return;pending='';const item={id:crypto.randomUUID(),text,status:'pending'};segments.push(item);queue.push(item);pump();}
function stop(){recording=false;clearInterval(timer);recognition?.stop();if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());$('voice-start').disabled=false;$('voice-stop').disabled=true;$('voice-transcript').readOnly=false;flush();renderDraft();}
function showReview(){const holder=$('voice-proposals');holder.replaceChildren();
 for(const p of draftPeople){const row=document.createElement('div');row.className='voice-person-review';const name=document.createElement('input');name.value=p.name;name.setAttribute('aria-label','Reviewed name for '+p.name);name.dataset.name=p.id;row.append(name);const select=document.createElement('select');select.dataset.match=p.id;select.setAttribute('aria-label','Match record for '+p.name);select.add(new Option('Choose: new person or existing record',''));select.add(new Option('Create new person','new'));select.add(new Option('Do not add this person','skip'));for(const existing of people)select.add(new Option('Use existing: '+existing.name,existing.id));row.append(select);const note=document.createElement('small');note.textContent='Possible matches: '+(people.filter(x=>clean(x.name)===clean(p.name)).map(x=>x.name).join(', ')||'none with this exact spelling')+'. Same-name mentions were grouped in the draft; review their identity.';row.append(note);const quotes=document.createElement('p');quotes.textContent=p.quotes.join('\n');row.append(quotes);holder.append(row);}
 for(const [i,l]of draftLinks.entries()){const label=document.createElement('label');label.className='check-label';const box=document.createElement('input');box.type='checkbox';box.dataset.link=i;const text=document.createElement('span');text.textContent=`${draftPeople.find(p=>p.id===l.from).name} → ${l.type==='parent'?'parent of':'partner of'} → ${draftPeople.find(p=>p.id===l.to).name}. Evidence: “${l.quote}”`;label.append(box,text);holder.append(label);}
 $('voice-review-panel').hidden=false;
}
function apply(){const mapping=new Map(),newPeople=[],newLinks=[];for(const p of draftPeople){const choice=$('voice-proposals').querySelector(`[data-match="${p.id}"]`).value,name=$('voice-proposals').querySelector(`[data-name="${p.id}"]`).value.trim();if(!choice){status('Choose new, existing or skip for each proposed person.');return;}if(choice==='skip')continue;if(!name){status('Every new person needs a reviewed name.');return;}if(choice==='new'){mapping.set(p.id,p.id);newPeople.push({id:p.id,name,birth:null,death:null,branch:'Voice',row:2,col:people.length+newPeople.length,bio:'Recorded memory: '+p.quotes.join(' '),events:[],sourceQuotes:p.quotes,personal:true});}else mapping.set(p.id,choice);}
 for(const box of $('voice-proposals').querySelectorAll('[data-link]:checked')){const l=draftLinks[Number(box.dataset.link)],a=mapping.get(l.from),b=mapping.get(l.to);if(!a||!b){status('A selected link refers to a skipped person. Uncheck it or resolve that person.');return;}if(!relationships.some(([x,y,t])=>x===a&&y===b&&t===l.type)&&!newLinks.some(([x,y,t])=>x===a&&y===b&&t===l.type))newLinks.push([a,b,l.type]);}
 if(!validGraph([...people,...newPeople],[...relationships,...newLinks])){status('Those choices would create a self-link or ancestry cycle. Review the matches and links.');return;}
 const next={people:[...saved.people,...newPeople],links:[...saved.links,...newLinks],stories:[...saved.stories,{id:crypto.randomUUID(),text:story,personIds:[...new Set(mapping.values())],reviewedAt:new Date().toISOString(),failedSegments:segments.filter(s=>s.status==='failed').map(s=>s.text)}]};
 try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{status('Browser storage could not save this story. Nothing was added. Download your transcript and try again.');return;}
 saved=next;people.push(...newPeople);relationships.push(...newLinks);refresh();$('voice-review-panel').hidden=true;draftPeople=[];draftLinks=[];segments=[];story='';$('voice-transcript').value='';renderDraft();status('Reviewed additions saved in this browser. Existing biographies were not overwritten.');
}
export function initVoice(onRefresh){refresh=onRefresh;document.addEventListener('family-key-forgotten',()=>{controller?.abort();stop();});draw=new FamilyCharts($('voice-tree'),id=>{const person=draftPeople.find(p=>p.id===id);$('voice-memory').textContent=person?'Draft memory for '+person.name+': '+person.quotes.join(' '):'';});
 $('voice-launch').onclick=()=>{$('voice-dialog').showModal();renderDraft();};$('voice-close').onclick=()=>{if(recording||processing){status('Stop recording and wait for processing before closing.');return;}$('voice-dialog').close();};$('voice-dialog').addEventListener('cancel',e=>{if(recording||processing){e.preventDefault();status('Stop recording before closing.');}});
 $('voice-start').onclick=async()=>{try{settings=requireAI();if(!$('voice-consent').checked)throw Error('Confirm speech processing below before starting.');const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)throw Error('Live speech recognition is unavailable in this browser. You can paste a transcript below and process it.');
 stream=await navigator.mediaDevices.getUserMedia({audio:true});audioParts=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)audioParts.push(e.data);};recorder.onstop=()=>{const link=$('voice-audio');if(link.dataset.url)URL.revokeObjectURL(link.dataset.url);link.href=URL.createObjectURL(new Blob(audioParts,{type:recorder.mimeType}));link.dataset.url=link.href;link.download=recorder.mimeType.includes('mp4')?'family-story.m4a':'family-story.webm';link.hidden=false;};recorder.start();
 recognition=new Speech();recognition.continuous=true;recognition.interimResults=true;recognition.lang=$('voice-language').value;
 recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const text=e.results[i][0].transcript;if(e.results[i].isFinal){story+=(story?' ':'')+text;pending+=(pending?' ':'')+text;}else interim+=text;}$('voice-transcript').value=story+(interim?'\n[Listening] '+interim:'');};
 recognition.onerror=e=>{status('Speech recognition error: '+e.error+'. Your audio can be downloaded; paste or correct the transcript to continue.');stop();};recognition.onend=()=>{if(recording){try{recognition.start();}catch{stop();status('Speech recognition stopped. Restart recording to continue.');}}else flush();};
 recording=true;recognition.start();timer=setInterval(flush,8000);$('voice-start').disabled=true;$('voice-stop').disabled=false;$('voice-transcript').readOnly=true;$('voice-review-panel').hidden=true;status('Listening. Proposals will appear as completed speech segments are processed.');
 }catch(e){stop();status(e.message);}};
 $('voice-stop').onclick=stop;$('voice-review').onclick=showReview;$('voice-apply').onclick=apply;
 $('voice-process').onclick=()=>{if(recording||processing){status('Stop recording and wait before processing an edited transcript.');return;}try{settings=requireAI();const text=$('voice-transcript').value.trim();if(!text)throw Error('Add a transcript first.');draftPeople=[];draftLinks=[];segments=[];queue=[];story=text;pending=text;$('voice-review-panel').hidden=true;flush();}catch(e){status(e.message);}};
 $('voice-retry').onclick=()=>{try{settings=requireAI();for(const s of segments.filter(s=>s.status==='failed')){s.status='pending';queue.push(s);}pump();}catch(e){status(e.message);}};
 $('voice-download').onclick=()=>{const blob=new Blob([$('voice-transcript').value],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='family-story-transcript.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
